NAV = ["Pierwsze kroki", "Stosy i daty", "Przeglądy", "Synchronizacja", "Importy i kopie zapasowe", "Bezpłatnie i płatnie", "Rozwiązywanie problemów", "Kontakt"]
TRB = "Rozwiązywanie problemów"
CONTACT = "Kontakt"
NOTE = "Ta strona jest tłumaczeniem angielskiej <en>strony pomocy</en>. W razie rozbieżności obowiązuje wersja angielska."
INTRO = "Krótka instrukcja do małej aplikacji. Jesteś tu nowy? Zacznij od góry. Coś nie działa? Przejdź do sekcji <t>Rozwiązywanie problemów</t>, a jeśli to nie pomoże, <c>napisz do mnie</c>."
G = {
0: "Twoje pierwsze zadania",
1: "Zacznij od garści prawdziwych zadań. Projekty i kategorie mogą poczekać, aż będą ci potrzebne.",
2: "1. Zapisz coś",
3: "Stuknij <strong>+</strong>, wpisz zadanie i zapisz je. Trafi do „{inbox}”, gdzie rzeczy czekają, aż zdecydujesz, co z nimi zrobić. Zadanie nie potrzebuje niczego więcej: ani projektu, ani daty.",
4: "2. Daj mu miejsce",
5: "Stuknij zadanie (na Macu kliknij), by zobaczyć, co można z nim zrobić. Najważniejsze jest przenoszenie. To, nad czym pracujesz, umieść w „<strong>{now}</strong>”. Może tam leżeć dni albo tygodnie; nic go stamtąd nie wypycha. „<strong>{next}</strong>” to to, do czego wrócisz potem, „<strong>{later}</strong>” jest dla tego, co chcesz zachować, ale czego nie ruszasz, a „<strong>{waiting}</strong>” dla tego, co utknęło w oczekiwaniu na kogoś innego.",
6: "<a href=\"#stacks-and-dates\">Następna sekcja</a> dobrze wyjaśnia stosy.",
7: "3. Trzymaj razem to, co do siebie pasuje",
8: "Wybierz <strong>{edit_plain}</strong> w działaniach zadania, by zmienić szczegóły i dodać notatki.",
9: "<strong>Projekt</strong> zbiera zadania jednej pracy: podróży, kursu, klienta. <strong>Kategoria</strong> to szeroka część twojego życia, na przykład Praca lub Dom. <strong>Grupa</strong> zbiera projekty. Projekt należy do jednej kategorii i może być w jednej grupie, a zmiana jednego lub drugiego obejmuje każde zadanie w projekcie. Zadanie bez projektu też może mieć kategorię.",
10: "4. Odnajdź się",
11: "Wyszukiwanie i filtr pomagają skupić się na jednym projekcie lub jednej kategorii. Na Macu i na iPadzie w poziomie pasek boczny pokazuje kategorie, grupy i projekty. Z poziomu filtra możesz zmieniać ich nazwy i kolejność.",
12: "W <strong>{more} → {appearance}</strong> wybierasz Automatyczny, Jasny lub Ciemny. Automatyczny podąża za twoim urządzeniem.",
13: "5. Zakończ",
14: "Stuknij kółko, gdy praca jest skończona. Zakończone zadanie opuszcza stosy, ale nie znika: <strong>{more} → {timeline}</strong> wymienia wszystko, co skończyłeś, dzień po dniu, a zadanie odhaczone za wcześnie możesz otworzyć ponownie.",
15: "Gdy listy zaczną wydawać się nieświeże, wypróbuj <a href=\"#reviews\">przegląd</a>.",
16: "<strong>Wypróbuj to.</strong> Dodaj „Zaplanować ogród”. Umieść je w „{now}”, gdy zbierasz pomysły. Gdy poprosisz wykonawcę o wycenę, przenieś je do „{waiting}” i ustaw przypomnienie na dzień, w którym chcesz się upomnieć. To samo zadanie od początku do końca.",
17: "Gdzie mieszka zadanie i kiedy na nie patrzeć",
18: "Stos mówi, co zamierzasz zrobić z zadaniem. Data mówi, kiedy chcesz o nim usłyszeć. DayHand celowo trzyma te dwie rzeczy osobno.",
19: "Pięć stosów",
20: "{inbox}",
21: "To, co właśnie zapisałeś i czego jeszcze nie umieściłeś.",
22: "{now}",
23: "To, nad czym aktywnie pracujesz, nawet jeśli zajmie to kilka dni.",
24: "{next}",
25: "To, do czego wrócisz, gdy będziesz miał miejsce. Nie znaczy: jutro.",
26: "{later}",
27: "Pomysły i plany, które chcesz zachować i których jeszcze nie ruszasz.",
28: "{waiting}",
29: "Praca, która potrzebuje odpowiedzi, dostawy, decyzji lub czyjejś części, zanim będziesz mógł iść dalej. Inaczej niż „{later}”: tu poszedłbyś dalej, gdybyś mógł.",
30: "Data nigdy nie przenosi zadania. Upływ czasu nie zmienia tego, gdzie ono leży; to ty decydujesz, kiedy się przesunie.",
31: "Oto jedno zadanie w ciągu tygodnia. W poniedziałek dodajesz „Przygotować prezentację”, z przypomnieniem na wtorek i terminem na piątek. We wtorek przypomnienie mówi, żebyś zaczął, więc przenosisz je do „{now}”. Pojawia się coś pilniejszego, więc trafia do „{later}” z nowym przypomnieniem na środę. W środę wraca do „{now}”. W czwartek wysyłasz szkic koledze i odkładasz zadanie do „{waiting}”. W piątek przychodzi odpowiedź, kończysz i odhaczasz. Jedno zadanie, jeden termin, który nigdy się nie zmienił, i nic nigdy nie było „spóźnione”.",
32: "Przypomnienia: spójrz na to jeszcze raz",
33: "Wybierz <strong>{remind_me}</strong> w działaniach zadania albo ustaw je w edytorze. <strong>{change_reminder}</strong> wybiera inny dzień, a <strong>{clear_reminder}</strong> je usuwa.",
34: "Przypomnienie odzywa się o <strong>9:00 w wybranym dniu</strong>, o ile powiadomienia są dozwolone dla DayHand. Jeśli ustawisz je na dziś po 9:00, nie ma już czego uruchamiać: zadanie zostaje oznaczone jako teraz wymagalne i nie następuje żadne powiadomienie. Selektor daty mówi o tym, gdy tak się stanie. (Przypomnienia utworzone przez starsze wersje mogą zachować swoją godzinę.)",
35: "Stuknij powiadomienie, a DayHand otworzy to zadanie. Odrzucenie go nie jest odpowiedzią; przypomnienie czeka w aplikacji dalej. Odpowiadasz na nie wyborem <strong>{keep_here}</strong> (jest we właściwym stosie, dzięki), przeniesieniem zadania, ukończeniem go albo wyborem innego dnia.",
36: "Kolory, flaga i plakietka",
37: "<strong>Pomarańczowa krawędź:</strong> przypomnienie nadejdzie w ciągu najbliższych trzech dni.",
38: "<strong>Czerwona krawędź:</strong> przypomnienie jest dziś albo już minęło. Znaczy „chciałeś na to spojrzeć”, a nie „jesteś spóźniony”.",
39: "<strong>Flaga w aplikacji:</strong> zbiera każde zadanie z czerwoną lub pomarańczową krawędzią, z dowolnego stosu. Liczba zlicza czerwone.",
40: "<strong>Plakietka na ikonie aplikacji:</strong> zlicza przypomnienia, które nadeszły i na które jeszcze nie odpowiedziałeś.",
41: "Zatem flaga i plakietka mogą się różnić i to w porządku. Odpowiedz na przypomnienie wyborem „{keep_here}”, a plakietka spadnie, podczas gdy zadanie zachowa czerwoną krawędź i zostanie we fladze, dopóki nie zmienisz lub nie usuniesz daty.",
42: "Terminy: gotowe do tego dnia",
43: "Dodaj termin w edytorze, gdy jest prawdziwa meta: oddanie, odnowienie, wysyłka. Aby dodać nowy, najpierw ustaw przypomnienie, a pole terminu pojawi się potem. Jeśli później usuniesz przypomnienie, termin, który już miałeś, pozostanie widoczny i edytowalny.",
44: "Termin nie wysyła powiadomienia i niczego nie przenosi. Po prostu jest zapisany przy zadaniu. Ustaw przypomnienie dość wcześnie, by móc jeszcze coś zrobić.",
45: "Brak powiadomienia? Zobacz, <a href=\"#notifications\">co sprawdzić</a>.",
46: "Przeglądy",
47: "Otwórz <strong>{more} → {review}</strong> i wybierz pomocnika. Każdy zadaje jedno pytanie o jedno zadanie lub jeden projekt, więc decydujesz, zamiast przewijać długą listę.",
48: "Przegląd zadań",
49: "{rv_inbox}",
50: "Gdzie to powinno trafić? Przenieś nowe zadania do pasującego stosu albo zostaw je, jeśli nie jesteś gotowy.",
51: "{rv_now}",
52: "Czy nadal aktywnie nad tym pracuję? Zostaw to, co aktywne, przenieś to, co się zmieniło, ukończ to, co skończone.",
53: "{rv_waiting}",
54: "Czy to może ruszyć dalej? Zostaw to, co naprawdę zablokowane, zabierz z powrotem to, co nie jest, albo ustaw przypomnienie, by się upomnieć.",
55: "{rv_next_later}",
56: "Czy to nadal aktualne? Wyciągnij na wierzch to, co ważne, i puść to, co nieważne.",
57: "{rv_all}",
58: "„{inbox}”, „{now}”, „{waiting}”, potem „{next}” i „{later}”, jednym przebiegiem. Zadanie, które przeniesiesz podczas przebiegu, nie wróci w tym samym przebiegu.",
59: "Pomocnik pokazuje zadanie i to, jak długo leży w swoim stosie. Zostaw je tam, gdzie jest, przenieś, edytuj, ukończ albo usuń. Przyciski stosów są w tym samym miejscu od zadania do zadania, więc kciuk się ich uczy.",
60: "Możesz przerwać w połowie i wrócić. Miejsce, do którego doszedłeś, jest zapisywane tylko na tym urządzeniu; inne urządzenie zaczyna własny przebieg. Zadania, które w międzyczasie nadejdą, czekają na następny przebieg.",
61: "<strong>Przegląd to decyzja, nie termin.</strong> „{keep_in_now}” to w pełni dobra odpowiedź, nawet dla zadania, które leży tam od miesiąca.",
62: "Przegląd projektów",
63: "<strong>{review_projects}</strong> zadaje jedno pytanie na projekt: <em>czy droga naprzód jest jasna?</em> Widzisz zadania według stosów, z kategorią i grupą.",
64: "<strong>{looks_right}:</strong> dobrze, idź dalej.",
65: "<strong>{add_task}:</strong> zapisz brakujący krok, z już wybranym tym projektem.",
66: "<strong>{review_these}:</strong> przejrzyj zadania tego projektu jedno po drugim.",
67: "<strong>{edit_project}:</strong> zmień nazwę, kategorię lub grupę.",
68: "Po dodaniu, edycji lub przeglądzie wracasz do tego samego projektu. Strzałka w lewym górnym rogu wraca do projektu, który właśnie opuściłeś, a krzyżyk kończy przegląd.",
69: "Najpierw idą projekty z niedokończoną pracą. Potem projekty, w których nic już nie zostało do zrobienia, żebyś mógł je zarchiwizować. Zarchiwizowane projekty są pomijane, a zadania bez projektu pojawiają się zamiast tego w przeglądach zadań.",
70: "Archiwizacja projektu, który ma jeszcze otwarte zadania, prosi cię o ich wcześniejsze ukończenie. Archiwum jest dla zakończonej pracy, a nie sposobem na uśpienie projektu; do tego użyj „{later}”.",
71: "Spojrzenie wstecz",
72: "<strong>{more} → {timeline}</strong> i Historia pojedynczego projektu pokazują, co skończyłeś. Są oddzielone od pomocników, którzy zajmują się pracą wciąż otwartą.",
73: "Synchronizacja",
74: "DayHand udostępnia twoje zadania przez jeden plik w twoim własnym iCloud Drive. Nie ma konta DayHand ani serwera. Na jednym urządzeniu nic z tego nie jest ci potrzebne.",
75: "Pierwsze urządzenie",
76: "Upewnij się, że iCloud Drive jest włączony.",
77: "Otwórz <strong>{more} → {sync} → {create_sync}</strong>.",
78: "Zapisz plik w folderze w iCloud Drive, który potem znajdziesz.",
79: "Daj iCloudowi chwilę na przesłanie go, zanim skonfigurujesz następne urządzenie.",
80: "Każde inne urządzenie",
81: "Zaloguj się tym samym Apple ID i upewnij się, że plik został pobrany.",
82: "Otwórz <strong>{more} → {sync} → {use_existing}</strong>.",
83: "Wybierz <strong>{merge_with}</strong>, co zachowuje zadania po obu stronach.",
84: "Wybierz <strong>ten sam plik</strong>, który utworzyłeś na pierwszym urządzeniu. Nie twórz drugiego pliku o tej samej nazwie; dwa pliki o jednej nazwie to dwa różne pliki.",
85: "Sprawdź swoje zadania i stan synchronizacji na obu urządzeniach.",
86: "<strong>Zastąpienie to co innego.</strong> „{replace_device}” wyrzuca to, co jest na tym urządzeniu, i bierze zamiast tego zadania z pliku. Jeśli możesz chcieć odzyskać obecną listę, najpierw zrób <a href=\"#backups\">kopię zapasową</a>.",
87: "DayHand sprawdza, czy wybrany plik naprawdę jest plikiem DayHand. Arkusz kalkulacyjny, cudzy JSON czy zdjęcie zostaną odrzucone, bo synchronizacja zapisuje do pliku i nadpisałaby go.",
88: "Dzień po dniu",
89: "Każde urządzenie trzyma własną kopię, więc możesz pracować offline. Zmiany spotykają się przez plik, gdy iCloud go dostarczy, a DayHand go odczyta. To może chwilę potrwać, a zamknięta aplikacja się nie spieszy. Nie oczekuj, że stanie się to natychmiast.",
90: "Unikaj edytowania tego samego zadania na dwóch urządzeniach, gdy oba są offline. Jeśli dwie wersje zadania się zderzą, wygrywa nowsza zmiana. DayHand nie scala dwóch zmian tego samego tytułu.",
91: "Gdy urządzenia się nie zgadzają",
92: "Zajrzyj do <strong>{more} → {sync}</strong> na każdym urządzeniu. „{not_syncing}” oznacza, że nie jest tam podłączony żaden plik.",
93: "Sprawdź, czy oba używają tego samego pliku w tym samym miejscu. Ta sama nazwa nie wystarczy.",
94: "Sprawdź, czy iCloud Drive jest połączony i plik skończył się pobierać, w Plikach lub w Finderze.",
95: "Otwórz DayHand na obu urządzeniach i stuknij <strong>{sync_now}</strong>. Przeczytaj wiersz pod przyciskiem.",
96: "Jeśli przeniosłeś lub zmieniłeś nazwę pliku i któreś urządzenie go zgubiło, zrób kopię zapasową tego urządzenia, przestań używać starego połączenia i wybierz właściwy plik jeszcze raz, wybierając Scal.",
97: "Odłączanie",
98: "<strong>{stop_using}</strong> odłącza to urządzenie. Zadania zostają. Jeśli chcesz tylko jednorazowo obejrzeć zapisaną kopię, niczego nie podłączając, użyj zamiast tego <a href=\"#restore\">{restore_file}</a>.",
99: "Nadal utknąłeś? <a href=\"#troubleshooting\">Daj mi znać</a> i napisz, co pokazuje stan synchronizacji na każdym urządzeniu.",
100: "Importy, eksporty i kopie zapasowe",
101: "Twoje zadania są twoje: wprowadź je, wyprowadź i odzyskaj. Import to jednorazowa kopia. DayHand nie pozostaje połączony z aplikacją, z której pochodzą.",
102: "Z Przypomnień Apple",
103: "Otwórz <strong>{more} → {tasks} → {import_reminders}</strong>.",
104: "Zezwól na dostęp do Przypomnień. Apple oferuje do czytania list tylko „pełny dostęp”. DayHand je czyta i nigdy nie zmienia.",
105: "Wybierz listy, stos, do którego trafią zadania, projekt lub kategorię oraz to, czy daty wykonania też mają się przenieść.",
106: "Obejrzyj podgląd, a potem potwierdź.",
107: "Data wykonania staje się przypomnieniem DayHand o 9:00, a nie terminem, a pierwotna data i godzina zostają w Notatkach. Powtarzające się przypomnienia są pomijane. Podzadania, tagi, załączniki i reguły list inteligentnych nie są przenoszone. Notatki, linki, miejsca i priorytety trafiają jako tekst, jeśli istnieją.",
108: "Najpierw tworzona jest kopia zapasowa. Zaimportuj te same listy ponownie na tym samym urządzeniu, a już zaimportowane zadania zostaną pominięte, także te, które usunąłeś. Na innym urządzeniu albo po zresetowaniu konta możesz dostać duplikaty.",
109: "Z Todoista",
110: "W Todoiście wyeksportuj swoje projekty jako pliki CSV.",
111: "Otwórz <strong>{more} → {tasks} → {import_todoist}</strong> i wybierz jeden lub więcej z tych plików.",
112: "Dla każdego pliku wybierz stos, projekt i kategorię oraz obejrzyj opcje dat.",
113: "Przeczytaj podgląd i ewentualne ostrzeżenia, a potem importuj.",
114: "Eksport projektów z Todoista nie zawiera ukończonych zadań. Daty, które rozpoznaje, stają się przypomnieniami o 9:00; terminy pozostają terminami. Opisy, komentarze i inne szczegóły, które potrafi odczytać, trafiają do Notatek. Podzadania stają się osobnymi zadaniami, z zapisanym zadaniem nadrzędnym i sekcją. Załączniki nie są pobierane. Powtarzające się harmonogramy nie są odtwarzane. Data, której DayHand nie rozumie, jest oznaczana; jeśli mimo to zaimportujesz zadanie, pierwotny tekst daty zostaje w Notatkach.",
115: "Najpierw tworzona jest kopia zapasowa. Ponowny import niezmienionego pliku o tej samej nazwie pomija już zaimportowane wiersze. Jeśli edytujesz eksport lub zmienisz jego nazwę, możesz dostać duplikaty.",
116: "<strong>Uważaj na powiadomienia.</strong> Przypomnienia Apple i Todoist nadal wysyłają własne powiadomienia, a przyszłe przypomnienie, które zaimportujesz, odezwie się także z DayHand. Zdecyduj, która aplikacja może ci przeszkadzać.",
117: "CSV DayHand",
118: "<strong>{more} → {tasks} → {export_csv}</strong> zapisuje przenośną kopię. <strong>{import_csv}</strong> oferuje <strong>{add_existing}</strong>, co scala CSV DayHand z twoją pracą, albo <strong>{replace_all}</strong>, co najpierw czyści obecne zadania. Pomyśl dwa razy, zanim wybierzesz to drugie.",
119: "Dla plików z Todoista użyj importu Todoist. Pliki CSV z innych aplikacji nie pasują do formatu DayHand. Jeśli chcesz przygotować plik ręcznie, najpierw wyeksportuj kilka zadań i skopiuj strukturę.",
120: "Kopie zapasowe",
121: "W <strong>{more} → {backups}</strong> stuknij <strong>{backup_now}</strong> przed czymkolwiek dużym. DayHand robi też własne, w dniach, gdy otwierasz aplikację, w kilku obrotowych miejscach: wczoraj, przedwczoraj i mniej więcej tydzień temu. To siatka bezpieczeństwa, a nie archiwum. Druga ręczna kopia tego samego dnia zastępuje pierwszą.",
122: "Aby zachować kopię w wybranym miejscu, użyj działania <strong>{share}</strong> przy kopii zapasowej. Na Macu kliknij kopię prawym przyciskiem, by Przywrócić, Udostępnić i Usunąć. Na iPhonie lub iPadzie przytrzymaj. Przesunięcie też działa.",
123: "Przywracanie",
124: "Jeśli możesz chcieć odzyskać obecne zadania, najpierw zrób kopię zapasową lub je wyeksportuj.",
125: "Stuknij kopię zapasową na liście albo wybierz <strong>{restore_file}</strong> i wskaż dowolny plik DayHand.",
126: "Przeczytaj dwie liczby w potwierdzeniu: zadania tutaj i zadania w pliku. Przywrócenie zastępuje obecne zadania i przywraca także kategorie i projekty.",
127: "Potwierdź tylko wtedy, gdy to kopia, której chcesz.",
128: "<strong>{restore_file} tylko czyta plik.</strong> Nie podłącza go do synchronizacji. Jeśli synchronizujesz, to pozostaje bez zmian, więc to, co przywrócisz, trafi na twoje pozostałe urządzenia. Aby obejrzeć kopię osobno, najpierw przestań synchronizować.",
129: "Aby mieć stałe połączenie ze wspólnym plikiem, zobacz <a href=\"#sync\">Synchronizację</a>.",
130: "Bezpłatnie i płatnie",
131: "Plan to bezpłatna aplikacja z jednym zakupem odblokowującym resztę. Bez subskrypcji.",
132: "<strong>Na jakim etapie jesteśmy.</strong> To wersja beta i wszystko jest odblokowane. Zakup, 30-dniowy okres próbny i Przywracanie zakupów nie zostały jeszcze zbudowane. Poniżej jest plan, żebyś wiedział, czego się spodziewać. Przełącznik testowy w becie pozwala mi wypróbować limity na własnych urządzeniach.",
133: "Bezpłatnie",
134: "Nieograniczone zadania, kategorie i grupy, do <strong>trzech aktywnych projektów</strong> i <strong>ostatnie 30 dni</strong> ukończonych zadań. Przeglądy, notatki, przypomnienia, terminy, synchronizacja, importy, eksporty i kopie zapasowe są w komplecie. Nie chcę, by przydatne części były za murem.",
135: "Odblokowanie",
136: "Jeden zakup, raz: nieograniczone aktywne projekty i cała historia ukończonych zadań, na iPhonie, iPadzie i Macu, z tym samym Apple ID. Wpiszę tu cenę, gdy będzie gotowa.",
137: "Przy limicie",
138: "Zarchiwizowane projekty się nie liczą, więc zarchiwizowanie skończonego projektu zwalnia miejsce, a przywrócenie jednego je zajmuje. Zapisanie zadania nigdy nie jest blokowane. Projekt, który już masz, pozostaje czytelny i edytowalny, nawet jeśli import przeniesie cię ponad trzy.",
139: "Ukończone zadania starsze niż 30 dni są tylko ukryte w {timeline}. Wyszukiwanie nadal je znajduje, a one zostają w twoich kopiach zapasowych i eksportach CSV. Nic nie jest usuwane dlatego, że nie zapłaciłeś.",
140: "Okres próbny",
141: "Planuję 30-dniowy okres próbny, który sam uruchamiasz. Gdy się skończy, aplikacja wraca do wersji bezpłatnej. Bez obciążenia i nic nie dzieje się automatycznie. Jeszcze go nie ma, tak samo jak Przywracania zakupów. Wyjaśnię oba tutaj, gdy się pojawią.",
}
